inline const BSP *GetBSP(const void *buf) {
  return ::flatbuffers::GetRoot<BSP>(buf);
}

inline const BSP *GetSizePrefixedBSP(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<BSP>(buf);
}

inline const char *BSPIdentifier() {
  return "$BSP";
}

inline bool BSPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, BSPIdentifier());
}

inline bool SizePrefixedBSPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, BSPIdentifier(), true);
}

template <bool B = false>
inline bool VerifyBSPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<BSP>(BSPIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedBSPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<BSP>(BSPIdentifier());
}

inline void FinishBSPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<BSP> root) {
  fbb.Finish(root, BSPIdentifier());
}

inline void FinishSizePrefixedBSPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<BSP> root) {
  fbb.FinishSizePrefixed(root, BSPIdentifier());
}

inline std::unique_ptr<BSPT> UnPackBSP(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<BSPT>(GetBSP(buf)->UnPack(res));
}

inline std::unique_ptr<BSPT> UnPackSizePrefixedBSP(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<BSPT>(GetSizePrefixedBSP(buf)->UnPack(res));
}

